     8	public class Database {
     9	    private static Connection connection;
    10	
    11	    public static void initialize(String dbUrl, String dbUser, String dbPassword) throws SQLException {
    12	        connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
    13	        createTables();
    14	        insertRooms();
    15	    }
    16	
    17	    public static Connection getConnection() {
    18	        return connection;
    19	    }
    20	
    21	    private static void createTables() throws SQLException {
    22	        try (Statement stmt = connection.createStatement()) {
    23	            stmt.execute("""
    24	                CREATE TABLE IF NOT EXISTS rooms (
    25	                    number INTEGER PRIMARY KEY,
    26	                    type VARCHAR(20) NOT NULL,
    27	                    capacity INTEGER NOT NULL,
    28	                    nightly_rate NUMERIC(10,2) NOT NULL
    29	                )
    30	            """);
    31	
    32	            stmt.execute("""
    33	                CREATE TABLE IF NOT EXISTS reservations (
    34	                    id BIGSERIAL PRIMARY KEY,
    35	                    room_number INTEGER NOT NULL REFERENCES rooms(number),
    36	                    guest_name VARCHAR(255) NOT NULL,
    37	                    guest_email VARCHAR(255) NOT NULL,
    38	                    guest_cpf VARCHAR(14) NOT NULL,
    39	                    check_in DATE NOT NULL,
    40	                    check_out DATE NOT NULL,
    41	                    guests INTEGER NOT NULL,
    42	                    rate_plan VARCHAR(20) NOT NULL,
    43	                    nights INTEGER NOT NULL,
    44	                    subtotal NUMERIC(10,2) NOT NULL,
    45	                    discount NUMERIC(10,2) NOT NULL,
    46	                    total NUMERIC(10,2) NOT NULL,
    47	                    status VARCHAR(20) NOT NULL,
    48	                    amount_paid NUMERIC(10,2) NOT NULL,
    49	                    refund NUMERIC(10,2)
    50	                )
    51	            """);
    52	
    53	            stmt.execute("""
    54	                CREATE TABLE IF NOT EXISTS messages (
    55	                    id BIGSERIAL PRIMARY KEY,
    56	                    channel VARCHAR(50) NOT NULL,
    57	                    to_address VARCHAR(255) NOT NULL,
    58	                    subject VARCHAR(255) NOT NULL,
    59	                    body TEXT NOT NULL
    60	                )
    61	            """);
    62	
    63	            stmt.execute("""
    64	                CREATE INDEX IF NOT EXISTS idx_reservations_room_dates
    65	                ON reservations(room_number, check_in, check_out)
    66	            """);
    67	
    68	            stmt.execute("""
    69	                CREATE INDEX IF NOT EXISTS idx_reservations_check_in
    70	                ON reservations(check_in)
    71	            """);
    72	        }
    73	    }
    74	
    75	    private static void insertRooms() throws SQLException {
    76	        try (Statement stmt = connection.createStatement()) {
    77	            stmt.execute("DELETE FROM rooms");
    78	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (101, 'STANDARD', 2, 249.90)");
    79	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (102, 'STANDARD', 2, 249.90)");
    80	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (201, 'DELUXE', 3, 389.90)");
    81	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (202, 'DELUXE', 3, 389.90)");
    82	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (301, 'SUITE', 4, 579.90)");
    83	        }
    84	    }
    85	}
