     8	import java.math.BigDecimal;
     9	import java.sql.SQLException;
    10	import java.time.LocalDate;
    11	import java.time.YearMonth;
    12	import java.util.List;
    13	
    14	public class ReportService {
    15	    private final ReservationRepository reservationRepository;
    16	    private final RoomRepository roomRepository;
    17	
    18	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
    19	        this.reservationRepository = reservationRepository;
    20	        this.roomRepository = roomRepository;
    21	    }
    22	
    23	    public String generateOccupancyReport(LocalDate date) throws SQLException {
    24	        StringBuilder csv = new StringBuilder();
    25	        csv.append("room,type,reservation,check_in,check_out\n");
    26	
    27	        int occupiedCount = 0;
    28	        for (int roomNumber : new int[]{101, 102, 201, 202, 301}) {
    29	            List<Reservation> reservations = reservationRepository.findByRoomOnDate(roomNumber, date);
    30	            for (Reservation reservation : reservations) {
    31	                if (reservation.getStatus() == ReservationStatus.CONFIRMED ||
    32	                    reservation.getStatus() == ReservationStatus.CHECKED_IN ||
    33	                    reservation.getStatus() == ReservationStatus.CHECKED_OUT) {
    34	                    String type = getRoomType(roomNumber);
    35	                    String checkInDate = formatDateISO(reservation.getCheckIn());
    36	                    String checkOutDate = formatDateISO(reservation.getCheckOut());
    37	                    csv.append(String.format("%d,%s,%d,%s,%s\n", roomNumber, type, reservation.getId(), checkInDate, checkOutDate));
    38	                    occupiedCount++;
    39	                }
    40	            }
    41	        }
    42	
    43	        csv.append(String.format("total,%d/5\n", occupiedCount));
    44	        return csv.toString();
    45	    }
    46	
    47	    public String generateRevenueReport(int year, int month) throws SQLException {
    48	        StringBuilder csv = new StringBuilder();
    49	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    50	
    51	        List<Reservation> reservations = reservationRepository.findByMonthAndStatus(year, month);
    52	        BigDecimal total = BigDecimal.ZERO;
    53	
    54	        for (Reservation reservation : reservations) {
    55	            String checkInDate = formatDateISO(reservation.getCheckIn());
    56	            String checkOutDate = formatDateISO(reservation.getCheckOut());
    57	            String status = reservation.getStatus().toString();
    58	            BigDecimal amount = reservation.getAmountPaid();
    59	            if (reservation.getRefund() != null) {
    60	                amount = amount.subtract(reservation.getRefund());
    61	            }
    62	
    63	            csv.append(String.format("%d,%d,%s,%s,%s,%s\n",
    64	                    reservation.getId(),
    65	                    reservation.getRoomNumber(),
    66	                    checkInDate,
    67	                    checkOutDate,
    68	                    status,
    69	                    formatBigDecimal(amount)));
    70	
    71	            total = total.add(amount);
    72	        }
    73	
    74	        csv.append(String.format("total,%s\n", formatBigDecimal(total)));
    75	        return csv.toString();
    76	    }
    77	
    78	    private String getRoomType(int roomNumber) {
    79	        return switch (roomNumber) {
    80	            case 101, 102 -> "STANDARD";
    81	            case 201, 202 -> "DELUXE";
    82	            case 301 -> "SUITE";
    83	            default -> "UNKNOWN";
    84	        };
    85	    }
    86	
    87	    private String formatDateISO(LocalDate date) {
    88	        return date.toString();
    89	    }
    90	
    91	    private String formatBigDecimal(BigDecimal value) {
    92	        return value.setScale(2, java.math.RoundingMode.HALF_EVEN).toPlainString();
    93	    }
    94	}
