     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.dto.CreateReservationRequest;
     4	import com.pousadamarealta.model.*;
     5	import com.pousadamarealta.notification.NotificationService;
     6	import com.pousadamarealta.repository.MessageRepository;
     7	import com.pousadamarealta.repository.ReservationRepository;
     8	import com.pousadamarealta.repository.RoomRepository;
     9	import com.pousadamarealta.util.DateUtils;
    10	import com.pousadamarealta.util.MoneyUtils;
    11	
    12	import java.math.BigDecimal;
    13	import java.sql.SQLException;
    14	import java.time.LocalDate;
    15	import java.util.List;
    16	import java.util.Optional;
    17	
    18	public class ReservationService {
    19	    private final ReservationRepository reservationRepository;
    20	    private final RoomRepository roomRepository;
    21	    private final MessageRepository messageRepository;
    22	    private final NotificationService notificationService;
    23	
    24	    public ReservationService(ReservationRepository reservationRepository, RoomRepository roomRepository,
    25	                           MessageRepository messageRepository, NotificationService notificationService) {
    26	        this.reservationRepository = reservationRepository;
    27	        this.roomRepository = roomRepository;
    28	        this.messageRepository = messageRepository;
    29	        this.notificationService = notificationService;
    30	    }
    31	
    32	    public Reservation createReservation(CreateReservationRequest request) throws Exception {
    33	        validateCreateRequest(request);
    34	
    35	        LocalDate checkIn = LocalDate.parse(request.checkIn);
    36	        LocalDate checkOut = LocalDate.parse(request.checkOut);
    37	        Room room = roomRepository.findByNumber(request.roomNumber)
    38	                .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
    39	
    40	        if (request.guests < 1 || request.guests > room.getCapacity()) {
    41	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
    42	        }
    43	
    44	        List<Reservation> conflicting = reservationRepository.findByRoomAndDateRange(
    45	                request.roomNumber, checkIn, checkOut);
    46	        if (!conflicting.isEmpty()) {
    47	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    48	        }
    49	
    50	        int nights = DateUtils.countNights(checkIn, checkOut);
    51	        BigDecimal subtotal = calculateNightsCost(room.getNightlyRate(), checkIn, checkOut);
    52	        BigDecimal discount = calculateDiscount(subtotal, RatePlan.valueOf(request.ratePlan));
    53	        BigDecimal total = subtotal.subtract(discount);
    54	
    55	        Reservation reservation = new Reservation(
    56	                0,
    57	                request.roomNumber,
    58	                request.guestName,
    59	                request.guestEmail,
    60	                request.guestCpf,
    61	                checkIn,
    62	                checkOut,
    63	                request.guests,
    64	                RatePlan.valueOf(request.ratePlan),
    65	                nights,
    66	                subtotal,
    67	                discount,
    68	                total,
    69	                ReservationStatus.PENDING,
    70	                BigDecimal.ZERO,
    71	                null
    72	        );
    73	
    74	        return reservationRepository.save(reservation);
    75	    }
    76	
    77	    public Reservation getReservation(long id) throws SQLException {
    78	        return reservationRepository.findById(id)
    79	                .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
    80	    }
    81	
    82	    public Reservation confirmReservation(long id) throws Exception {
    83	        Reservation reservation = getReservation(id);
    84	
    85	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    86	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    87	        }
    88	
    89	        reservation.setAmountPaid(reservation.getTotal());
    90	        reservation.setStatus(ReservationStatus.CONFIRMED);
    91	        reservationRepository.update(reservation);
    92	
    93	        sendConfirmationEmail(reservation);
    94	        notificationService.notifyConfirmed(reservation);
    95	
    96	        return reservation;
    97	    }
    98	
    99	    public Reservation checkIn(long id) throws SQLException {
   100	        Reservation reservation = getReservation(id);
   101	
   102	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   103	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   104	        }
   105	
   106	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   107	        reservationRepository.update(reservation);
   108	
   109	        return reservation;
   110	    }
   111	
   112	    public Reservation checkOut(long id) throws SQLException {
   113	        Reservation reservation = getReservation(id);
   114	
   115	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   116	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   117	        }
   118	
   119	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   120	        reservationRepository.update(reservation);
   121	
   122	        return reservation;
   123	    }
   124	
   125	    public Reservation cancelReservation(long id) throws Exception {
   126	        Reservation reservation = getReservation(id);
   127	
   128	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   129	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   130	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   131	        }
   132	
   133	        boolean wasConfirmed = reservation.getStatus() == ReservationStatus.CONFIRMED;
   134	
   135	        if (wasConfirmed) {
   136	            BigDecimal refund = calculateRefund(reservation);
   137	            reservation.setRefund(refund);
   138	        }
   139	
   140	        reservation.setStatus(ReservationStatus.CANCELLED);
   141	        reservationRepository.update(reservation);
   142	
   143	        if (wasConfirmed) {
   144	            notificationService.notifyCancelled(reservation);
   145	        }
   146	
   147	        return reservation;
   148	    }
   149	
   150	    private BigDecimal calculateRefund(Reservation reservation) {
   151	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
   152	            return BigDecimal.ZERO;
   153	        }
   154	        return reservation.getAmountPaid();
   155	    }
   156	
   157	    private void sendConfirmationEmail(Reservation reservation) throws SQLException {
   158	        String subject = "Reserva confirmada - Pousada Maré Alta";
   159	        String document = generateDocument(reservation);
   160	        String body = String.format("""
   161	                Olá, %s!
   162	
   163	                Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
   164	
   165	                %s
   166	
   167	                A entrada é a partir das 14h, e a saída, até as 12h.
   168	                Até breve!""",
   169	                reservation.getGuestName(),
   170	                document);
   171	
   172	        Message message = new Message(0, "EMAIL", reservation.getGuestEmail(), subject, body);
   173	        messageRepository.save(message);
   174	    }
   175	
   176	    public String generateDocument(Reservation reservation) {
   177	        StringBuilder sb = new StringBuilder();
   178	        sb.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
   179	        sb.append(String.format("Hóspede: %s (CPF %s)\n", reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
   180	        sb.append(String.format("Quarto: %d (%s)\n", reservation.getRoomNumber(), getRoomType(reservation.getRoomNumber())));
   181	
   182	        String nightsLabel = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
   183	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n",
   184	                DateUtils.formatDate(reservation.getCheckIn()),
   185	                DateUtils.formatDate(reservation.getCheckOut()),
   186	                nightsLabel));
   187	
   188	        sb.append(String.format("Diárias: %s\n", MoneyUtils.formatMoneyPrecise(reservation.getSubtotal())));
   189	
   190	        if (reservation.getDiscount().signum() > 0) {
   191	            sb.append(String.format("Desconto: %s\n", MoneyUtils.formatMoneyPrecise(reservation.getDiscount())));
   192	        }
   193	
   194	        sb.append(String.format("Total: %s", MoneyUtils.formatMoneyPrecise(reservation.getTotal())));
   195	
   196	        return sb.toString();
   197	    }
   198	
   199	    private String getRoomType(int roomNumber) {
   200	        return switch (roomNumber) {
   201	            case 101, 102 -> "STANDARD";
   202	            case 201, 202 -> "DELUXE";
   203	            case 301 -> "SUITE";
   204	            default -> "UNKNOWN";
   205	        };
   206	    }
   207	
   208	    private String formatCpf(String cpf) {
   209	        if (cpf.length() != 11) return cpf;
   210	        return String.format("%s.%s.%s-%s",
   211	                cpf.substring(0, 3),
   212	                cpf.substring(3, 6),
   213	                cpf.substring(6, 9),
   214	                cpf.substring(9));
   215	    }
   216	
   217	    private BigDecimal calculateNightsCost(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
   218	        BigDecimal totalCost = BigDecimal.ZERO;
   219	        LocalDate current = checkIn;
   220	
   221	        while (current.isBefore(checkOut)) {
   222	            BigDecimal nightRate = baseRate;
   223	            if (DateUtils.isHighSeason(current)) {
   224	                nightRate = MoneyUtils.applyHighSeasonRate(baseRate);
   225	            }
   226	            totalCost = totalCost.add(nightRate);
   227	            current = current.plusDays(1);
   228	        }
   229	
   230	        return MoneyUtils.round(totalCost);
   231	    }
   232	
   233	    private BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
   234	        if (ratePlan == RatePlan.STANDARD) {
   235	            return BigDecimal.ZERO;
   236	        }
   237	        return MoneyUtils.calculateDiscount(subtotal, 15);
   238	    }
   239	
   240	    public void validateCreateRequest(CreateReservationRequest request) {
   241	        if (request.roomNumber == 0 || request.guestName == null || request.guestEmail == null ||
   242	            request.guestCpf == null || request.checkIn == null || request.checkOut == null ||
   243	            request.ratePlan == null) {
   244	            throw new IllegalArgumentException("INVALID_REQUEST");
   245	        }
   246	
   247	        try {
   248	            LocalDate checkIn = LocalDate.parse(request.checkIn);
   249	            LocalDate checkOut = LocalDate.parse(request.checkOut);
   250	
   251	            if (!checkOut.isAfter(checkIn)) {
   252	                throw new IllegalArgumentException("INVALID_REQUEST");
   253	            }
   254	
   255	            if (request.guests < 1) {
   256	                throw new IllegalArgumentException("INVALID_REQUEST");
   257	            }
   258	        } catch (Exception e) {
   259	            if (e.getMessage() != null && e.getMessage().contains("INVALID_REQUEST")) {
   260	                throw e;
   261	            }
   262	            throw new IllegalArgumentException("INVALID_REQUEST");
   263	        }
   264	    }
   265	}
