     8	public class GovernanceNotifier implements ReservationNotifier {
     9	    private static final String GOVERNANCE_EMAIL = "governanca@pousadamarealta.com.br";
    10	    private final MessageRepository messageRepository;
    11	
    12	    public GovernanceNotifier(MessageRepository messageRepository) {
    13	        this.messageRepository = messageRepository;
    14	    }
    15	
    16	    @Override
    17	    public void onReservationConfirmed(Reservation reservation) throws Exception {
    18	        String subject = String.format("Reserva confirmada - quarto %d", reservation.getRoomNumber());
    19	        String body = String.format(
    20	                "Entrada: %s\nSaída: %s\nHóspedes: %d",
    21	                DateUtils.formatDate(reservation.getCheckIn()),
    22	                DateUtils.formatDate(reservation.getCheckOut()),
