    49	
    50	        int nights = DateUtils.countNights(checkIn, checkOut);
    51	        BigDecimal subtotal = calculateNightsCost(room.getNightlyRate(), checkIn, checkOut);
    52	        BigDecimal discount = calculateDiscount(subtotal, RatePlan.valueOf(request.ratePlan));
    53	        BigDecimal total = subtotal.subtract(discount);
