   133	    private static DocumentResponse toDocumentResponse(Reservation reservation, ReservationService reservationService) {
   134	        DocumentResponse response = new DocumentResponse();
   135	        response.title = "Comprovante de reserva";
   136	        response.reservationId = reservation.getId();
   137	        response.guestName = reservation.getGuestName();
