   179	    private static String formatCpf(String cpf) {
   180	        if (cpf.length() != 11) return cpf;
   181	        return String.format("%s.%s.%s-%s",
   182	                cpf.substring(0, 3),
   183	                cpf.substring(3, 6),
   184	                cpf.substring(6, 9),
   185	                cpf.substring(9));
   186	    }
