   150	    private static void handleError(io.javalin.http.Context ctx, String error) {
   151	        if (error.equals("ROOM_NOT_FOUND")) {
   152	            ctx.status(404);
   153	            ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
   154	        } else if (error.equals("RESERVATION_NOT_FOUND")) {
   155	            ctx.status(404);
   156	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   157	        } else if (error.equals("ROOM_UNAVAILABLE")) {
   158	            ctx.status(409);
   159	            ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for these dates"));
   160	        } else if (error.equals("OPERATION_NOT_ALLOWED")) {
   161	            ctx.status(409);
   162	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "This operation is not allowed in the current reservation state"));
   163	        } else if (error.equals("CAPACITY_EXCEEDED")) {
   164	            ctx.status(422);
   165	            ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
   166	        } else if (error.equals("INVALID_REQUEST")) {
   167	            ctx.status(400);
   168	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
   169	        } else {
   170	            ctx.status(500);
   171	            ctx.json(new ErrorResponse("INTERNAL_ERROR", error));
   172	        }
   173	    }
